-- =============================================================
-- FULL DATABASE RESET — DFW Terminal D
--
-- One-shot script that wipes and rebuilds nav_nodes, nav_edges,
-- and amenities from the canonical source files. Run this when
-- the graph or amenity data is messed up and you want to start
-- over from a known-good state.
--
-- Sources concatenated below:
--   1. terminal_d_sql-nodes corrected position.sql  (1353 nodes w/ lat/lng)
--   2. terminal_d_sql-edges corrected position.sql  (5944 edges)
--   3. upload amenities.sql                         (128 amenities,
--      each linked to its nearest nav_node by lat/lng)
--
-- DROP order respects FK dependencies:
--   amenities -> nav_nodes
--   nav_edges -> nav_nodes
-- so amenities and nav_edges drop before nav_nodes.
--
-- Wrapped in a single transaction. If anything fails, nothing
-- is committed.
-- =============================================================

BEGIN;

-- ---------- step 0: drop existing tables ----------
DROP TABLE IF EXISTS amenities CASCADE;
DROP TABLE IF EXISTS nav_edges CASCADE;
DROP TABLE IF EXISTS nav_nodes CASCADE;

-- ---------- step 1: recreate nav_nodes ----------
CREATE TABLE nav_nodes (
    id        SERIAL PRIMARY KEY,
    label     TEXT,
    x         FLOAT,
    y         FLOAT,
    node_type TEXT,
    zone      TEXT DEFAULT 'public',
    lat       DOUBLE PRECISION,
    lng       DOUBLE PRECISION
);

-- ---------- step 2: recreate nav_edges ----------
CREATE TABLE nav_edges (
    id        SERIAL PRIMARY KEY,
    from_node INT REFERENCES nav_nodes(id),
    to_node   INT REFERENCES nav_nodes(id),
    distance  FLOAT,
    direction TEXT
);

