-- ---------- step 5: recreate amenities and link to nearest nav_node ----------
-- (body lifted from upload amenities.sql; the DROP at the top is redundant
--  with step 0 above but harmless)

-- Step 1: Recreate the amenities table
DROP TABLE IF EXISTS amenities CASCADE;

CREATE TABLE amenities (
    ID          SERIAL PRIMARY KEY,
    nodeID      INTEGER REFERENCES nav_nodes(id),
    name        TEXT NOT NULL,
    type        TEXT NOT NULL,
    wheelChairAccessible TEXT DEFAULT 'unknown',
    status      TEXT DEFAULT 'open',
    crowdLevel  INTEGER DEFAULT 0,
    latitude    DOUBLE PRECISION,
    longitude   DOUBLE PRECISION
);

-- Step 2: Load CSV rows into a temp table
CREATE TEMP TABLE csv_import (
    name        TEXT,
    description TEXT,
    latitude    DOUBLE PRECISION,
    longitude   DOUBLE PRECISION,
    altitude    DOUBLE PRECISION
);

